const r = await Promise.allSettled([
  tools.exec_command({cmd:"ls -lah /app/dataset && rg --files /app/dataset | sort",workdir:"/app",max_output_tokens:6000}),
  tools.exec_command({cmd:"cat /app/dataset/farms.csv /app/dataset/farm_registry.csv /app/dataset/sensors_calibration.json /app/dataset/maintenance_notes.txt",workdir:"/app",max_output_tokens:20000}),
