const r=await tools.exec_command({cmd:"python - <<'PY'
from pathlib import Path
import pandas as pd
for farm in pd.read_csv('/app/dataset/farm_registry.csv').farm_id:
 p=Path('/app/dataset')/f'production_{farm}.csv';b=p.read_bytes();enc='utf-16' if b[:2] in (b'\xff\xfe',b'\xfe\xff') else 'utf-8-sig';sep=';' if ';' in b.decode(enc).splitlines()[3] else ','
 df=pd.read_csv(p,skiprows=3,sep=sep,encoding=enc,dtype=str)
 temp=pd.to_numeric(df['inverter_temperature_C'].str.replace(',','.'),errors='coerce');sp=df.loc[temp>85]
 if len(sp):
  print('\n',farm,'spikes',len(sp));print(sp.iloc[:,[0,1,-3,-2]].to_string(index=False))
PY",workdir:"/app",max_output_tokens:6000});text(r);
